def view_transaction(tx_hash):
    try:
        # Get transaction details
        tx = web3.eth.get_transaction(tx_hash)
        if tx:
            # Decode the 'input' field (contains the data payload)
            data = tx['input'].decode('utf-8') if isinstance(tx['input'], bytes) else web3.to_text(tx['input'])
            print(f"Transaction {web3.to_hex(tx_hash)} details:")
            print(f"  From: {tx['from']}")
            print(f"  To: {tx['to']}")
            print(f"  Block: {tx['blockNumber']}")
            print(f"  Data: {data}")
        else:
            print(f"Transaction {web3.to_hex(tx_hash)} not found.")
    except Web3RPCError as e:
        print(f"Error retrieving transaction: {e}")


def log_data(position, message):
    data_str = f"Timestamp: {int(time.time())}, Position: {position}, Message: {message}"
    txn = {
        'to': account,  # Send to self or any address
        'value': 0,
        'gas': 2000000,
        'gasPrice': web3.to_wei('1', 'gwei'),
        'nonce': web3.eth.get_transaction_count(account),
        'data': data_str.encode()
    }
    tx_hash = web3.eth.send_transaction(txn)
    print(f"Transaction hash: {web3.to_hex(tx_hash)}")
    view_transaction(tx_hash)
    return tx_hash


    # Example usage
position = "x:1.0 y:2.0 z:0.0"  # From robot's pose
